package com.arcsys.constructiq;

import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.text.InputType;import android.view.*;import android.widget.*;import java.text.*;import java.util.*;

public class MainActivity extends Activity{
 final int NAVY=Color.rgb(11,31,51),TEAL=Color.rgb(22,160,133),BG=Color.rgb(244,247,250),TEXT=Color.rgb(28,43,57),MUTED=Color.rgb(99,115,129),WHITE=Color.WHITE,PALE=Color.rgb(230,246,242); SharedPreferences sp; LinearLayout root,body; TextView title;
 public void onCreate(Bundle b){super.onCreate(b);sp=getSharedPreferences("constructiq",0);home();}
 TextView tv(String s,int z,int c,boolean bold){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(c);v.setPadding(dp(4),dp(5),dp(4),dp(5));if(bold)v.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return v;}
 int dp(int x){return (int)(x*getResources().getDisplayMetrics().density+.5f);} GradientDrawable bg(int color,int r){GradientDrawable g=new GradientDrawable();g.setColor(color);g.setCornerRadius(dp(r));return g;}
 void shell(String name){root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(BG);LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);bar.setPadding(dp(16),dp(10),dp(12),dp(10));bar.setBackgroundColor(NAVY);TextView logo=tv("A",24,WHITE,true);logo.setGravity(Gravity.CENTER);logo.setBackground(bg(TEAL,12));bar.addView(logo,new LinearLayout.LayoutParams(dp(44),dp(44)));title=tv(name,20,WHITE,true);LinearLayout.LayoutParams tp=new LinearLayout.LayoutParams(0,-2,1);tp.setMargins(dp(12),0,0,0);bar.addView(title,tp);if(!name.equals("ConstructIQ")){Button h=button("Home");h.setOnClickListener(v->home());bar.addView(h,new LinearLayout.LayoutParams(-2,dp(42)));}root.addView(bar);ScrollView sc=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(dp(14),dp(14),dp(14),dp(30));sc.addView(body);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);}
 Button button(String s){Button b=new Button(this);b.setText(s);b.setTextColor(WHITE);b.setTextSize(13);b.setAllCaps(false);b.setBackground(bg(TEAL,10));return b;}
 void section(String s){TextView v=tv(s,18,TEXT,true);v.setPadding(dp(4),dp(16),0,dp(8));body.addView(v);}
 void card(String head,String sub,View.OnClickListener l){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(dp(16),dp(13),dp(16),dp(13));c.setBackground(bg(WHITE,16));TextView h=tv(head,16,TEXT,true),d=tv(sub,13,MUTED,false);c.addView(h);c.addView(d);if(l!=null)c.setOnClickListener(l);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,0,0,dp(10));body.addView(c,p);}
 EditText input(String hint,String key,String def){EditText e=new EditText(this);e.setHint(hint);e.setText(sp.getString(key,def));e.setTextSize(15);e.setTextColor(TEXT);e.setHintTextColor(MUTED);e.setSingleLine();e.setPadding(dp(12),dp(10),dp(12),dp(10));e.setBackground(bg(WHITE,10));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(52));p.setMargins(0,0,0,dp(9));body.addView(e,p);return e;}
 double n(EditText e){try{return Double.parseDouble(e.getText().toString().trim());}catch(Exception x){return 0;}}
 String money(double x){return "₹"+new DecimalFormat("#,##0.00").format(x);} String num(double x){return new DecimalFormat("#,##0.###").format(x);}
 void home(){shell("ConstructIQ");TextView hero=tv("Arcsys Geospatial Pvt. Ltd.\nCivil Estimation • Site Control • Calculators",20,NAVY,true);hero.setPadding(dp(16),dp(18),dp(16),dp(18));hero.setBackground(bg(PALE,16));body.addView(hero);section("Project snapshot");double est=Double.longBitsToDouble(sp.getLong("estimate",Double.doubleToLongBits(0))),prog=Double.longBitsToDouble(sp.getLong("progress",Double.doubleToLongBits(0)));card("Current estimate  "+money(est),"Project: "+sp.getString("pname","Not set")+"  •  Progress: "+num(prog)+"%",v->project());section("Workspace");card("Projects & Dashboard","Project identity, budget, area and physical progress",v->project());card("Smart Estimate","Area-based estimate with OH, profit, contingency and GST",v->estimate());card("Civil Calculators","Concrete, steel, brickwork, plaster, excavation, flooring, paint and slope",v->calculators());card("BOQ / Cost Items","Add priced work items and maintain an offline running BOQ",v->boq());card("Site Monitoring / DPR","Daily progress, manpower, weather, quantity and notes",v->site());card("Unit Converter","Length, area, volume and engineering conversions",v->converter());card("Notes & Decisions","Offline project notebook for site instructions and decisions",v->notes());card("Method & Safety","Estimation checks, measurement discipline and field-use guidance",v->about());}
 void project(){shell("Project Dashboard");section("Project setup");EditText name=input("Project name","pname",""),client=input("Client","client",""),loc=input("Location","loc",""),area=input("Built-up area (sq ft)","area","1500"),budget=input("Approved budget ₹","budget","0"),progress=input("Physical progress %","progressText","0");Button save=button("Save project");body.addView(save,new LinearLayout.LayoutParams(-1,dp(52)));save.setOnClickListener(v->{sp.edit().putString("pname",name.getText().toString()).putString("client",client.getText().toString()).putString("loc",loc.getText().toString()).putString("area",area.getText().toString()).putString("budget",budget.getText().toString()).putString("progressText",progress.getText().toString()).putLong("progress",Double.doubleToRawLongBits(n(progress))).apply();toast("Project saved offline");});section("Controls");card("Budget vs estimate",money(parse(budget.getText().toString())-Double.longBitsToDouble(sp.getLong("estimate",Double.doubleToLongBits(0))))+" balance against current estimate",null);card("Field principle","Record dimensions, source of rate, revision and measurement evidence. Keep estimate assumptions separate from certified quantities.",null);}
 double parse(String s){try{return Double.parseDouble(s.trim());}catch(Exception e){return 0;}}
 void estimate(){shell("Smart Estimate");section("Inputs");EditText area=input("Built-up area (sq ft)","e_area",sp.getString("area","1500")),rate=input("Base rate ₹/sq ft","e_rate","2200"),oh=input("Overhead %","e_oh","10"),profit=input("Profit %","e_profit","10"),cont=input("Contingency %","e_cont","3"),gst=input("GST %","e_gst","18");TextView out=tv("Enter values and calculate",18,NAVY,true);out.setPadding(dp(14),dp(18),dp(14),dp(18));out.setBackground(bg(PALE,14));body.addView(out);Button calc=button("Calculate & Save Estimate");LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-1,dp(54));bp.setMargins(0,dp(12),0,0);body.addView(calc,bp);calc.setOnClickListener(v->{double base=n(area)*n(rate),over=base*n(oh)/100,p=(base+over)*n(profit)/100,c=(base+over+p)*n(cont)/100,pre=base+over+p+c,tax=pre*n(gst)/100,total=pre+tax;out.setText("Base: "+money(base)+"\nOverhead: "+money(over)+"\nProfit: "+money(p)+"\nContingency: "+money(c)+"\nGST: "+money(tax)+"\n\nTOTAL: "+money(total));sp.edit().putLong("estimate",Double.doubleToRawLongBits(total)).putString("e_area",area.getText().toString()).putString("e_rate",rate.getText().toString()).putString("e_oh",oh.getText().toString()).putString("e_profit",profit.getText().toString()).putString("e_cont",cont.getText().toString()).putString("e_gst",gst.getText().toString()).apply();});card("Important","This is a concept estimate. Tender/contract values should use item-wise quantities, approved specifications and applicable rate sources.",null);}
 void calculators(){shell("Civil Calculators");section("Quantity & material calculators");card("Concrete Mix Materials","Wet volume → dry volume → cement bags, sand and aggregate",v->calcDialog("Concrete","Wet volume m³","Dry factor","Cement ratio","Sand ratio","Aggregate ratio",(a)->{double sum=a[2]+a[3]+a[4],dry=a[0]*a[1];return "Cement ≈ "+num((dry*a[2]/sum)/0.035)+" bags\nSand ≈ "+num(dry*a[3]/sum)+" m³\nAggregate ≈ "+num(dry*a[4]/sum)+" m³";},"1","1.54","1","1.5","3"));card("Steel Weight","d²/162 × total length",v->calcDialog("Steel","Diameter mm","Total length m",null,null,null,(a)->"Steel weight ≈ "+num(a[0]*a[0]/162*a[1])+" kg", "12","100"));card("Brickwork","Wall volume and approximate brick count",v->calcDialog("Brickwork","Length m","Height m","Thickness m","Brick unit volume m³","Wastage %",(a)->{double vol=a[0]*a[1]*a[2],br=vol/a[3]*(1+a[4]/100);return "Masonry volume = "+num(vol)+" m³\nApprox. bricks/blocks = "+num(br);},"10","3","0.23","0.002","5"));card("Plaster","Area, wet mortar and dry mortar",v->calcDialog("Plaster","Length m","Height m","Thickness m","Dry factor","Wastage %",(a)->{double ar=a[0]*a[1],wet=ar*a[2],dry=wet*a[3]*(1+a[4]/100);return "Area = "+num(ar)+" m²\nWet mortar = "+num(wet)+" m³\nDry mortar ≈ "+num(dry)+" m³";},"10","3","0.012","1.33","5"));card("Excavation","L × B × D × Nos",v->calcDialog("Excavation","Length m","Width m","Depth m","Nos",null,(a)->"Excavation = "+num(a[0]*a[1]*a[2]*a[3])+" m³","10","0.9","1.2","1"));card("Flooring / Tiles","Area plus wastage",v->calcDialog("Flooring","Length m","Width m","Wastage %",null,null,(a)->"Purchase area ≈ "+num(a[0]*a[1]*(1+a[2]/100))+" m²","5","4","7"));card("Paint","Area ÷ coverage × coats + wastage",v->calcDialog("Paint","Paint area m²","Coverage m²/L/coat","Coats","Wastage %",null,(a)->"Paint ≈ "+num((a[0]/a[1])*a[2]*(1+a[3]/100))+" L","100","10","2","5"));card("Slope / Gradient","Rise and run → percent and 1:N",v->calcDialog("Slope","Rise","Run",null,null,null,(a)->{double p=a[1]==0?0:a[0]/a[1]*100,n=a[0]==0?0:a[1]/a[0];return "Slope = "+num(p)+"%\nGradient ≈ 1:"+num(n);},"1","100"));}
 interface Formula{String run(double[] a);} void calcDialog(String name,String h1,String h2,String h3,String h4,String h5,Formula f,String...defs){LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(18),dp(8),dp(18),0);String[] hs={h1,h2,h3,h4,h5};ArrayList<EditText> es=new ArrayList<>();for(int i=0;i<hs.length;i++)if(hs[i]!=null){EditText e=new EditText(this);e.setHint(hs[i]);e.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);e.setText(i<defs.length?defs[i]:"");box.addView(e);es.add(e);}new AlertDialog.Builder(this).setTitle(name).setView(box).setPositiveButton("Calculate",(d,w)->{double[] a=new double[es.size()];for(int i=0;i<a.length;i++)a[i]=n(es.get(i));new AlertDialog.Builder(this).setTitle(name+" Result").setMessage(f.run(a)).setPositiveButton("OK",null).show();}).setNegativeButton("Cancel",null).show();}
 void boq(){shell("BOQ / Cost Items");section("Add item");EditText desc=input("Description","x_desc",""),unit=input("Unit (m3, m2, kg, No., LS)","x_unit","m3"),qty=input("Quantity","x_qty","0"),rate=input("Rate ₹","x_rate","0");Button add=button("Add BOQ item");body.addView(add,new LinearLayout.LayoutParams(-1,dp(52)));TextView list=tv(sp.getString("boq","No BOQ items yet."),14,TEXT,false);list.setPadding(dp(14),dp(16),dp(14),dp(16));list.setBackground(bg(WHITE,14));section("Running BOQ");body.addView(list);add.setOnClickListener(v->{double amt=n(qty)*n(rate);String old=sp.getString("boq","");String line="• "+desc.getText()+" | "+num(n(qty))+" "+unit.getText()+" × "+money(n(rate))+" = "+money(amt)+"\n";String all=old+line;sp.edit().putString("boq",all).apply();list.setText(all);desc.setText("");});Button clear=button("Clear BOQ test data");body.addView(clear,new LinearLayout.LayoutParams(-1,dp(48)));clear.setOnClickListener(v->{sp.edit().remove("boq").apply();list.setText("No BOQ items yet.");});}
 void site(){shell("Site Monitoring / DPR");section("Daily entry");EditText activity=input("Activity / work front","d_activity",""),weather=input("Weather","d_weather","Clear"),man=input("Manpower","d_man","0"),qty=input("Executed quantity","d_qty","0"),unit=input("Unit","d_unit","m3"),note=input("Delay / quality / safety note","d_note","");Button save=button("Save DPR entry");body.addView(save,new LinearLayout.LayoutParams(-1,dp(52)));TextView log=tv(sp.getString("dpr","No DPR entries yet."),13,TEXT,false);log.setPadding(dp(14),dp(16),dp(14),dp(16));log.setBackground(bg(WHITE,14));section("Recent log");body.addView(log);save.setOnClickListener(v->{String date=new SimpleDateFormat("dd MMM yyyy HH:mm",Locale.US).format(new Date());String line=date+"\n"+activity.getText()+" | "+qty.getText()+" "+unit.getText()+" | Manpower "+man.getText()+" | "+weather.getText()+"\n"+note.getText()+"\n────────────\n";String all=line+sp.getString("dpr","");sp.edit().putString("dpr",all).apply();log.setText(all);activity.setText("");note.setText("");});}
 void converter(){shell("Unit Converter");section("Fast engineering conversions");card("Length: metre ↔ feet","1 m = 3.28084 ft",v->convertDialog("Length",3.28084,"m","ft"));card("Area: m² ↔ sq ft","1 m² = 10.7639 sq ft",v->convertDialog("Area",10.7639,"m²","sq ft"));card("Volume: m³ ↔ cu ft","1 m³ = 35.3147 cu ft",v->convertDialog("Volume",35.3147,"m³","cu ft"));card("Volume: m³ ↔ litres","1 m³ = 1000 L",v->convertDialog("Volume",1000,"m³","L"));card("Mass: kg ↔ metric tonne","1000 kg = 1 t",v->convertDialog("Mass",0.001,"kg","t"));card("Pressure: MPa ↔ N/mm²","Numerically equal",v->convertDialog("Pressure",1,"MPa","N/mm²"));}
 void convertDialog(String name,double factor,String a,String b){EditText e=new EditText(this);e.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);e.setHint("Value in "+a);new AlertDialog.Builder(this).setTitle(name+" conversion").setView(e).setPositiveButton("Convert",(d,w)->{double x=n(e);new AlertDialog.Builder(this).setMessage(num(x)+" "+a+" = "+num(x*factor)+" "+b+"\n\n"+num(x)+" "+b+" = "+num(x/factor)+" "+a).setPositiveButton("OK",null).show();}).setNegativeButton("Cancel",null).show();}
 void notes(){shell("Notes & Decisions");section("Offline notebook");EditText e=input("Write instruction, decision, reminder or site observation","noteDraft","");e.setSingleLine(false);e.setMinLines(4);Button add=button("Add note");body.addView(add,new LinearLayout.LayoutParams(-1,dp(52)));TextView notes=tv(sp.getString("notes","No notes yet."),14,TEXT,false);notes.setPadding(dp(14),dp(16),dp(14),dp(16));notes.setBackground(bg(WHITE,14));section("Notebook");body.addView(notes);add.setOnClickListener(v->{String date=new SimpleDateFormat("dd MMM yyyy HH:mm",Locale.US).format(new Date());String all="• "+date+" — "+e.getText()+"\n\n"+sp.getString("notes","");sp.edit().putString("notes",all).apply();notes.setText(all);e.setText("");});}
 void about(){shell("Method & Safety");section("Built for field testing");card("Offline-first","Core project data, estimates, BOQ, DPR and notes are stored locally on this device. No account or Play Store is required for this test build.",null);card("Estimation discipline","Use approved drawings/specifications. Separate concept estimates from detailed BOQ. Record rate source/date. Apply waste only where justified. Reconcile theoretical and actual consumption.",null);card("Measurement discipline","Use item-specific measurement rules and certified dimensions. Keep previous, current and cumulative quantities separate for RA bills. Record deductions and variations explicitly.",null);card("Structural caution","Concrete mix, reinforcement, member sizes and structural quantities must follow approved structural design and applicable standards. Calculator outputs are estimating aids, not structural design approval.",null);card("Roadmap","Next production stage: multi-project database, user roles, cloud sync, photos/GPS, PDF/Excel reports, rate libraries, approvals, procurement, stock, RA billing, GIS map and drawing takeoff.",null);card("Version","Arcsys ConstructIQ 0.1.0-test • Native Android • Designed for direct sideload testing",null);}
 void toast(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();}
}
